+  min-height: 100vh;
+  display: flex;
+  flex-direction: column;
+}
+
+/* ===== Skip link ===== */
+.skip-link {
+  position: absolute;
+  top: -100%;
+  left: 0;
+  padding: 0.75rem 1.25rem;
+  background: var(--focus-ring);
+  color: #000;
+  font-weight: 700;
+  text-decoration: none;
+  border-radius: 0 0 var(--radius) 0;
+  z-index: 999;
+  transition: top 0.1s;
+}
+
+.skip-link:focus {
+  top: 0;
+}
+
+/* ===== Header ===== */
+.site-header {
+  border-bottom: 1px solid var(--border);
+  padding: 1rem 1.5rem;
+}
+
+.header-inner {
+  max-width: 760px;
+  margin: 0 auto;
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+}
+
+.header-logo {
+  font-size: 1.5rem;
+}
+
+.header-title {
+  font-size: 1.125rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  letter-spacing: 0.02em;
+}
+
+/* ===== Main ===== */
+main {
+  flex: 1;
+  max-width: 760px;
+  width: 100%;
+  margin: 0 auto;
+  padding: 2rem 1.5rem 4rem;
+}
+
+/* ===== Hero ===== */
+.hero {
+  text-align: center;
+  margin-bottom: 2.5rem;
+  padding-bottom: 2rem;
+  border-bottom: 1px solid var(--border);
+}
+
+.hero h1 {
+  font-size: clamp(1.75rem, 5vw, 2.75rem);
+  font-weight: 800;
+  line-height: 1.15;
+  background: linear-gradient(135deg, #c4bbff 0%, var(--accent) 55%, #f0a0d0 100%);
+  -webkit-background-clip: text;
+  -webkit-text-fill-color: transparent;
+  background-clip: text;
+  margin-bottom: 0.5rem;
+}
+
+.hero-sub {
+  color: var(--text-secondary);
+  font-size: 1.0625rem;
+}
+
+/* ===== FAQ List ===== */
+.faq-list {
+  display: flex;
+  flex-direction: column;
+  gap: 0.75rem;
+}
+
+/* ===== FAQ Item (.example wrapper) ===== */
+.example {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+  overflow: hidden;
+}
+
+.example h3 {
+  margin: 0;
+  font-size: 1rem;
+}
+
+/* ===== Trigger button ===== */
+.faq-trigger {
+  all: unset;
+  box-sizing: border-box;
+  display: flex;
+  align-items: center;
+  gap: 0.875rem;
+  width: 100%;
+  padding: 1.125rem 1.5rem;
+  font-size: 1.0625rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  cursor: pointer;
+  text-align: left;
+  transition: background-color 0.15s ease, color 0.15s ease;
+}
+
+.faq-trigger:hover {
+  background-color: var(--bg-trigger-hover);
+}
+
+.faq-trigger:focus-visible {
+  outline: 3px solid var(--focus-ring);
+  outline-offset: -3px;
+  border-radius: var(--radius);
+}
+
+.faq-trigger[aria-expanded="true"] {
+  color: var(--accent);
+}
+
+/* Animated chevron */
+.faq-trigger::after {
+  content: '';
+  display: block;
+  width: 9px;
+  height: 9px;
+  border-right: 2.5px solid var(--accent);
+  border-bottom: 2.5px solid var(--accent);
+  transform: rotate(45deg);
+  margin-left: auto;
+  flex-shrink: 0;
+  transition: transform 0.2s ease;
+}
+
+.faq-trigger[aria-expanded="true"]::after {
+  transform: rotate(-135deg);
+}
+
+/* Category badge */
+.faq-badge {
+  flex-shrink: 0;
+  font-size: 0.6875rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 0.07em;
+  padding: 0.2em 0.65em;
+  border-radius: 99px;
+  background: rgba(139, 124, 248, 0.15);
+  color: var(--accent);
+  border: 1px solid rgba(139, 124, 248, 0.3);
+}
+
+/* ===== Details panel ===== */
+.details {
+  padding: 0 1.5rem 1.25rem;
+  color: var(--text-secondary);
+  font-size: 0.9875rem;
+  line-height: 1.75;
+  border-top: 1px solid var(--border);
+  animation: revealPanel 0.2s ease-out both;
+}
+
+.details p {
+  margin: 0;
+  padding-top: 1.125rem;
+}
+
+@keyframes revealPanel {
+  from {
+    opacity: 0;
+    transform: translateY(-6px);
+  }
+  to {
+    opacity: 1;
+    transform: translateY(0);
+  }
+}
+
+/* ===== Reduced motion ===== */
+@media (prefers-reduced-motion: reduce) {
+  .details {
+    animation: none;
+  }
+  .faq-trigger,
+  .faq-trigger::after {
+    transition: none;
+  }
+  .skip-link {
+    transition: none;
+  }
+}
+
+/* ===== Footer ===== */
+.site-footer {
+  border-top: 1px solid var(--border);
+  padding: 1.25rem 1.5rem;
+  text-align: center;
+  color: var(--text-muted);
+  font-size: 0.875rem;
+}
+
+/* ===== Forced Colors (high contrast mode) ===== */
+@media (forced-colors: active) {
+  .hero h1 {
+    -webkit-text-fill-color: unset;
+    background: none;
+    color: CanvasText;
+  }
+  .faq-trigger::after {
+    border-color: ButtonText;
+  }
+  .faq-badge {
+    background: Canvas;
+    color: ButtonText;
+    border-color: ButtonText;
+  }
+  .example {
+    border-color: ButtonText;
+  }
+}
+
+/* ===== Reflow: narrow viewports ===== */
+@media (max-width: 400px) {
+  main {
+    padding: 1.25rem 1rem 3rem;
+  }
+  .faq-trigger {
+    padding: 1rem 1.125rem;
+    font-size: 1rem;
+  }
+  .details {
+    padding: 0 1.125rem 1rem;
+  }
+}
+
')

