// ─── Data ────────────────────────────────────────────────────────────────────

const FAQ_DATA = [
  {
    question: 'Why do cats purr?',
    answer:
      'Cats purr for a variety of reasons beyond simple contentment. Purring occurs at frequencies between 25–150 Hz, which research suggests may promote bone healing and reduce pain. Cats also purr when stressed, injured, or giving birth — using it as a self-soothing mechanism.',
    badge: 'Behavior',
  },
  {
    question: 'Why do cats knead with their paws?',
