    badge: 'Behavior',
  },
  {
    question: 'Do cats always land on their feet?',
    answer:
      'Cats have a highly developed "righting reflex" — an innate ability to orient themselves upright during a fall. However, "always" is an overstatement. Cats can be injured in falls, especially from low heights where the reflex hasn\'t fully engaged, or from very great heights.',
    badge: 'Anatomy',
  },
  {
    question: 'Why do cats sleep so much?',
    answer:
      'Cats are crepuscular predators whose natural hunting style demands short, intense bursts of energy. Sleeping 12–16 hours a day conserves energy between hunts. Even well-fed domestic cats retain this deep evolutionary pattern.',
    badge: 'Behavior',
  },
  {
    question: 'Why do cats bring home dead animals?',
    answer:
      'Cats are instinctive hunters, and when they bring prey home they are generally believed to be sharing their catch with their "family" — you. Some researchers also suggest cats may be trying to teach their humans to hunt, much as mother cats teach their kittens.',
    badge: 'Instinct',
  },
  {
    question: 'Why do cats knock things off tables?',
    answer:
      'Cats use their paws to investigate objects and test whether they might be prey. A falling object also provides novel sensory stimulation. Cats quickly learn that knocking things over captures human attention, making the behaviour highly self-reinforcing.',
    badge: 'Behavior',
  },
  {
    question: 'How long do cats typically live?',
    answer:
      'Indoor domestic cats typically live 12–18 years, with many reaching their early twenties. The oldest verified cat on record, Creme Puff of Austin, Texas, lived to 38 years. Genetics, diet, veterinary care, and whether a cat lives indoors all significantly affect lifespan.',
    badge: 'Health',
  },
  {
    question: 'Are cats truly solitary animals?',
    answer:
      'Wild and feral cats are largely solitary hunters, but domestic cats have adapted to form complex social bonds — both with humans and with other cats. Many domestic cats actively seek companionship, play, and physical affection, challenging the "aloof loner" stereotype.',
    badge: 'Social',
  },
];

// ─── Components ──────────────────────────────────────────────────────────────

/**
 * Badge — small decorative label indicating a question's category.
 * Marked aria-hidden because the question text is already self-descriptive.
 *
 * @param {string} text
 * @returns {HTMLSpanElement}
 */
function Badge(text) {
  const el = document.createElement('span');
  el.className = 'faq-badge';
  el.textContent = text;
  el.setAttribute('aria-hidden', 'true');
  return el;
}

/**
 * FAQItem — a single disclosure widget: a trigger button that shows/hides
 * an answer panel. Follows the ARIA disclosure pattern:
 *   - Trigger is a <button> with aria-expanded
 *   - Panel receives `hidden` via JS (not hard-coded in HTML) so content
 *     remains visible in no-JS / reader-mode environments
 *   - Escape collapses an open panel and returns focus to the trigger
 *
 * @param {{ question: string, answer: string, badge: string }} props
 * @returns {HTMLDivElement}
 */
function FAQItem({ question, answer, badge }) {
  const wrapper = document.createElement('div');
  wrapper.className = 'example';

  // h2: questions sit directly under the page's h1 — no level should be skipped
  const heading = document.createElement('h2');

  const trigger = document.createElement('button');
  trigger.type = 'button';
  trigger.className = 'faq-trigger';
  trigger.setAttribute('aria-expanded', 'false');

  if (badge) {
    trigger.appendChild(Badge(badge));
  }
  trigger.append(document.createTextNode(question));

  heading.appendChild(trigger);

  // Controlled content panel — class required by spec
  const panel = document.createElement('div');
  panel.className = 'details';
  panel.hidden = true; // set via JS so no-JS users see all content

  const p = document.createElement('p');
  p.textContent = answer;
  panel.appendChild(p);

  // Toggle on click
  trigger.addEventListener('click', () => {
    const isOpen = trigger.getAttribute('aria-expanded') === 'true';
    trigger.setAttribute('aria-expanded', String(!isOpen));
    panel.hidden = isOpen;
  });

  // Escape closes an open panel (optional enhancement per ARIA APG)
  trigger.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && trigger.getAttribute('aria-expanded') === 'true') {
      trigger.setAttribute('aria-expanded', 'false');
      panel.hidden = true;
    }
  });

  wrapper.appendChild(heading);
  wrapper.appendChild(panel);

  return wrapper;
}

/**
 * FAQList — renders a collection of FAQItem components into a container element.
 *
 * @param {{ items: typeof FAQ_DATA, container: HTMLElement }} props
 */
function FAQList({ items, container }) {
  const fragment = document.createDocumentFragment();
  items.forEach((item) => fragment.appendChild(FAQItem(item)));
  container.appendChild(fragment);
}

// ─── Mount ───────────────────────────────────────────────────────────────────

FAQList({
  items: FAQ_DATA,
  container: document.getElementById('faq-root'),
});
